$qiquestions = [
    [$qitext('What are the indications for herbs that regulate the Qi?','¿Cuáles son las indicaciones de las hierbas que regulan Qi?'),$qitext('Qi stagnation produces fullness, then distension, then pain as severity increases. Lung involvement gives chest constraint, cough or wheeze; Spleen-Stomach gives abdominal distension, belching, nausea or irregular stool; Liver gives emotional, hypochondriac, breast or menstrual symptoms.','El estancamiento de Qi produce plenitud, luego distensión y finalmente dolor al aumentar la gravedad. Pulmón da opresión torácica, tos o sibilancia; Bazo-Estómago da distensión, eructos, náusea o heces irregulares; Hígado da síntomas emocionales, hipocondríacos, mamarios o menstruales.')],
    [$qitext('What are the characteristics of Qi-regulating herbs, and what precautions should be observed?','¿Cuáles son las características de las hierbas que regulan Qi y qué precauciones deben observarse?'),$qitext('Most are pungent and warm because pungency moves and warmth activates Qi. They commonly enter Spleen, Stomach, Liver, Large Intestine and Lung. Their movement can worsen bleeding, heavy menstruation or pregnancy risk, and their warmth/dryness can injure Yin and fluids.','La mayoría son acres y tibias porque lo acre mueve y el calor activa Qi. Suelen entrar en Bazo, Estómago, Hígado, Intestino Grueso y Pulmón. Su movimiento puede agravar sangrado, menstruación abundante o riesgo en embarazo, y su calor/sequedad puede lesionar Yin y líquidos.')],
    [$qitext('How do Ju Hong, Chen Pi, Ju Luo, Ju Ye and Ju He differ?','¿Cómo se diferencian Ju Hong, Chen Pi, Ju Luo, Ju Ye y Ju He?'),$qitext('Ju Hong targets Cold Damp-Phlegm cough; Chen Pi regulates Spleen-Stomach Qi and dries Dampness. Outside this current list: Ju Luo opens collaterals and removes chronic Phlegm, Ju Ye moves Liver Qi and breast nodules, and Ju He descends Cold accumulation in the Liver channel.','Ju Hong trata tos por Flema-Humedad Fría; Chen Pi regula Qi de Bazo-Estómago y seca Humedad. Fuera de esta lista: Ju Luo abre colaterales y elimina Flema crónica, Ju Ye mueve Qi de Hígado y nódulos mamarios, y Ju He desciende acumulación Fría en el canal de Hígado.')],
    [$qitext('What are the differences between Zhi Shi and Zhi Ke?','¿Cuáles son las diferencias entre Zhi Shi y Zhi Ke?'),$qitext('Zhi Shi is the unripe fruit: stronger, more bitter and forcefully downward for severe obstruction and constipation. Zhi Ke is nearly ripe: gentler, slower and more horizontal across Upper and Middle Jiao for chest and epigastric distension.','Zhi Shi es el fruto inmaduro: más fuerte, amargo y descendente para obstrucción grave y estreñimiento. Zhi Ke está casi maduro: más suave, lento y horizontal en Jiao Superior y Medio para distensión torácica y epigástrica.')],
    [$qitext('How do Qing Pi, Chen Pi and Zhi Ke differ?','¿Cómo se diferencian Qing Pi, Chen Pi y Zhi Ke?'),$qitext('Qing Pi is strongest and focuses on Liver/Gallbladder Qi, pain and accumulation. Chen Pi is moderate and focuses on Spleen-Stomach Qi, appetite, nausea and Dampness. Zhi Ke has similar strength to Chen Pi but moves across the chest and upper abdomen.','Qing Pi es la más fuerte y se enfoca en Qi de Hígado/Vesícula, dolor y acumulación. Chen Pi es moderada y trata Qi de Bazo-Estómago, apetito, náusea y Humedad. Zhi Ke tiene fuerza similar a Chen Pi pero se mueve por tórax y abdomen superior.')],
    [$qitext('What are the characteristics of Xiang Fu?','¿Cuáles son las características de Xiang Fu?'),$qitext('Xiang Fu is gentle yet effective: pungent movement, slight bitterness to reduce constraint Heat and sweetness to soften the Liver. It spreads Qi through San Jiao without harshly injuring Liver Yin/Blood, making it the chief Qi regulator and first-line gynecologic herb.','Xiang Fu es suave pero eficaz: movimiento acre, amargor leve que reduce Calor por constricción y dulzor que suaviza Hígado. Extiende Qi por San Jiao sin lesionar agresivamente Yin/Sangre de Hígado, por eso es jefa de reguladoras de Qi y primera opción ginecológica.')],
    [$qitext('Which herbs promote Liver-Qi movement, and what distinguishes the current-list herbs?','¿Qué hierbas promueven movimiento de Qi de Hígado y qué distingue a las de la lista actual?'),$qitext('Xiang Fu is gentle and gynecologic; Qing Pi is strongest for Excess accumulation; Mu Xiang bridges Liver/Gallbladder with digestive and intestinal Qi; Chuan Lian Zi is bitter, cold, toxic and best when stagnation generates Liver Fire. Other herbs in Yang’s answer are outside this current list.','Xiang Fu es suave y ginecológica; Qing Pi es más fuerte para acumulación de Exceso; Mu Xiang conecta Hígado/Vesícula con Qi digestivo e intestinal; Chuan Lian Zi es amarga, fría, tóxica y mejor cuando el estancamiento genera Fuego de Hígado. Las otras hierbas de Yang están fuera de esta lista actual.')],
    [$qitext('Which herbs regulate Qi in the abdomen, and what distinguishes the current-list herbs?','¿Qué hierbas regulan Qi en abdomen y qué distingue a las de la lista actual?'),$qitext('Chen Pi and Zhi Ke favor upper-abdominal distension. Mu Xiang moves the whole abdomen and intestine with pain. Da Fu Pi adds urination and edema. Zhi Shi is the strongest downward breaker for intestinal accumulation. Yang also names Hou Po and Sha Ren, which are outside this current category.','Chen Pi y Zhi Ke favorecen distensión abdominal superior. Mu Xiang mueve todo abdomen e intestino con dolor. Da Fu Pi añade orina y edema. Zhi Shi es la ruptura descendente más fuerte para acumulación intestinal. Yang también nombra Hou Po y Sha Ren, fuera de esta categoría actual.')],
    [$qitext('Which herbs can influence Qi movement throughout the body?','¿Qué hierbas pueden influir en el movimiento de Qi en todo el cuerpo?'),$qitext('Qi movement is broader than this category: herbs may disperse or descend Lung Qi, raise or lower Middle-Jiao Qi, move the intestines, harmonize Heart-Kidney, raise Yang, spread Liver Qi, anchor Liver Yang or coordinate Qi and Blood. Board reasoning should identify organ, direction and paired mechanism before choosing.','El movimiento de Qi es más amplio que esta categoría: las hierbas pueden dispersar o descender Qi de Pulmón, elevar o bajar Qi del Jiao Medio, mover intestinos, armonizar Corazón-Riñón, elevar Yang, extender Qi de Hígado, anclar Yang de Hígado o coordinar Qi y Sangre. Para el Board identifica órgano, dirección y mecanismo antes de elegir.')],
];
