<section class="single-herbs-guide__section" aria-labelledby="topic-eighteen-foundations"><h4 id="topic-eighteen-foundations"><?php echo s($qitext('Herbs that regulate the Qi: general introduction','Hierbas que regulan Qi: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($qitext('Do not memorize these as eleven interchangeable “Qi movers.” Locate the traffic jam, determine its direction and severity, then identify the secondary mechanism: Dampness, Phlegm, food, Cold, Heat, water, Blood or menstrual dysfunction.','No memorices estas once como “movilizadoras de Qi” intercambiables. Localiza el atasco, determina dirección y gravedad, y luego el mecanismo secundario: Humedad, Flema, alimento, Frío, Calor, agua, Sangre o disfunción menstrual.')); ?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($qitext('Lung / Phlegm','Pulmón / Flema')); ?></strong><span>Ju Hong · Chen Pi</span></div><div><strong><?php echo s($qitext('Middle / bowel','Medio / intestino')); ?></strong><span>Zhi Shi · Mu Xiang · Da Fu Pi</span></div><div><strong><?php echo s($qitext('Liver / emotions','Hígado / emociones')); ?></strong><span>Xiang Fu · Qing Pi · Chuan Lian Zi</span></div><div><strong><?php echo s($qitext('Rebellious / chest','Rebelde / tórax')); ?></strong><span>Chen Xiang · Tan Xiang</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($qitext('Enter the Qi traffic-control tower.','Entra a la torre de control del tráfico de Qi.')); ?></p><p><?php echo s($qitext('Chen Pi clears the kitchen; Ju Hong dries the Lung floor; Qing Pi cuts Liver traffic. Zhi Shi is the heavy wrecking ball and Zhi Ke the lighter rolling ball. Da Fu Pi opens the water drain. Xiang Fu directs feelings and cycles; Mu Xiang turns the abdominal mill. Chen Xiang lowers the elevator to Kidney, Tan Xiang opens the Heart corridor, and Chuan Lian Zi is the cold toxic firefighter.','Chen Pi despeja cocina; Ju Hong seca el piso de Pulmón; Qing Pi corta tráfico de Hígado. Zhi Shi es la bola pesada y Zhi Ke la ligera. Da Fu Pi abre drenaje de agua. Xiang Fu dirige emociones y ciclos; Mu Xiang gira molino abdominal. Chen Xiang baja el elevador a Riñón, Tan Xiang abre corredor de Corazón y Chuan Lian Zi es la bombera fría y tóxica.')); ?></p></aside><ol class="single-herbs-guide__category-herbs"><?php foreach($qiherbs as $herb):?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($herb['name']);?></strong><em><?php echo s($herb['latin']);?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($qitext('Current category list','Lista vigente de la categoría'));?></span></div><p><?php echo s($herb['identity']);?></p></li><?php endforeach;?></ol></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-eighteen-yang"><h4 id="topic-eighteen-yang"><?php echo s($qitext('Yang comparative fingerprints','Huellas comparativas de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($qitext('The values below are relative study indices from Yang, not doses or clinical percentages. Only herbs in this current category are graphed.','Los valores son índices relativos de estudio de Yang, no dosis ni porcentajes clínicos. Solo se grafican hierbas de esta categoría actual.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach($qicharts as $chart):?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]);?></h5><small><?php echo s($chart[1]);?></small><?php foreach($chart[2] as $name=>$value):?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name);?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int)$value;?>%"></span></span><b><?php echo (int)$value;?></b></div><?php endforeach;?></article><?php endforeach;?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($qitext('Outside-list note:','Nota fuera de lista:'));?></strong> <?php echo s($qitext('Yang’s complete figures also include Hou Po, Sha Ren, Ma Huang, Xi Xin, Jie Geng, Xing Ren, Ting Li Zi, Shi Gao, Lai Fu Zi, Bing Lang, Sang Bai Pi, Bai Qian, Qian Hu, Li Zhi He, Wu Yao, Mei Gui Hua and Fo Shou. They are excluded here to preserve the current Board-category boundary.','Las figuras completas de Yang también incluyen Hou Po, Sha Ren, Ma Huang, Xi Xin, Jie Geng, Xing Ren, Ting Li Zi, Shi Gao, Lai Fu Zi, Bing Lang, Sang Bai Pi, Bai Qian, Qian Hu, Li Zhi He, Wu Yao, Mei Gui Hua y Fo Shou. Se excluyen aquí para conservar el límite de la categoría Board actual.'));?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-eighteen-profiles"><h4 id="topic-eighteen-profiles"><?php echo s($qitext('Individual herb profiles','Perfiles individuales de las hierbas'));?></h4><div class="single-herbs-guide__profiles"><?php foreach($qiherbs as $herb):?><details class="single-herbs-guide__profile"<?php echo $herb['name']==='Chen Pi'?' open':'';?>><summary><span class="single-herbs-guide__profile-name"><?php echo s($herb['name']);?></span><span class="single-herbs-guide__profile-latin"><?php echo s($herb['latin']);?></span><span class="single-herbs-guide__profile-meta"><?php echo s($herb['properties']);?> · <?php echo s($herb['channels']);?></span></summary><div class="single-herbs-guide__profile-body"><dl><dt><?php echo s($qitext('Study dose','Dosis de estudio'));?></dt><dd><?php echo s($herb['dose']);?></dd><dt><?php echo s($qitext('Identity','Identidad'));?></dt><dd><?php echo s($herb['identity']);?></dd><dt><?php echo s($qitext('Exam clue','Pista de examen'));?></dt><dd><?php echo s($herb['clue']);?></dd><dt><?php echo s($qitext('Memory','Memoria'));?></dt><dd class="single-herbs-guide__profile-memory"><?php echo s($herb['memory']);?></dd><dt><?php echo s($qitext('Unique fingerprint','Huella única'));?></dt><dd><?php echo s($herb['unique']);?></dd><dt><?php echo s($qitext('Formula boundary','Límite de fórmulas'));?></dt><dd class="single-herbs-guide__profile-formulas"><?php if($herb['formulas']):foreach($herb['formulas'] as $i=>$formula):?><?php if($i):?> · <?php endif;?><?php $path='/study-guide/comparisons/formula-navigator-'.sprintf('%02d',$formula[0]).'-'.$formula[1].($ises?'-es':'').'.html';$url=new moodle_url($path,['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a href="<?php echo $url->out(false);?>"><strong><?php echo s($formula[2]);?></strong></a> (<?php echo s($formula[3]);?>)<?php endforeach;?> — <?php echo s($qitext('current 63-formula roster.','listado vigente de 63 fórmulas.'));?><?php else:echo s($qitext('No chief or co-chief role in the current 63-formula Board roster.','No tiene papel principal ni coprincipal en el listado Board vigente de 63 fórmulas.'));endif;?></dd><dt><?php echo s($qitext('Safety','Seguridad'));?></dt><dd class="single-herbs-guide__profile-safety"><?php echo s($herb['caution']);?></dd></dl></div></details><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-eighteen-comparisons"><h4 id="topic-eighteen-comparisons"><?php echo s($qitext('High-yield comparisons','Comparaciones de alto rendimiento'));?></h4><div class="single-herbs-guide__comparisons"><?php foreach($qicomparisons as $comparison):?><?php $url=new moodle_url($ises?$comparison[1]:$comparison[0],['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false);?>"><strong><?php echo s($comparison[2]);?></strong><span><?php echo s($comparison[3]);?></span><small><?php echo s($qitext('Open full comparison →','Abrir comparación completa →'));?></small></a><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-eighteen-questions"><h4 id="topic-eighteen-questions"><?php echo s($qitext('Yang questions shown in full','Preguntas de Yang mostradas completas'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($qitext('All nine chapter 10 questions appear in full on the card fronts. Answers are condensed for Board recall while preserving category boundaries.','Las nueve preguntas del capítulo 10 aparecen completas al frente. Las respuestas se condensan para repaso Board conservando límites de categoría.'));?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($qitext('Card','Tarjeta'));?>" data-of-label="<?php echo s($qitext('of','de'));?>"><?php foreach($qiquestions as $i=>$question):?><article class="single-herbs-guide__yang-card<?php echo $i===0?' is-active':'';?>" data-yang-card aria-hidden="<?php echo $i===0?'false':'true';?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($qitext('Question','Pregunta'));?> <?php echo $i+1;?> <?php echo s($qitext('of','de'));?> <?php echo count($qiquestions);?> · Yang, <?php echo s($qitext('Chapter','capítulo'));?> 10</span><p class="single-herbs-guide__yang-question"><?php echo s($question[0]);?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($qitext('Answer','Respuesta'));?> <?php echo $i+1;?></span><p class="single-herbs-guide__yang-answer"><?php echo s($question[1]);?></p></div></article><?php endforeach;?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($qitext('Previous','Anterior'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($qitext('Show answer','Mostrar respuesta'));?>" data-hide-label="<?php echo s($qitext('Show question','Mostrar pregunta'));?>"><?php echo s($qitext('Show answer','Mostrar respuesta'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($qitext('Next','Siguiente'));?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($qitext('Card','Tarjeta'));?> 1 <?php echo s($qitext('of','de'));?> <?php echo count($qiquestions);?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-eighteen-recall"><h4 id="topic-eighteen-recall"><?php echo s($qitext('Quick recall','Repaso rápido'));?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($qitext('Strongest downward breaker for bowel obstruction?','¿Ruptura descendente más fuerte para obstrucción intestinal?'));?></summary><p><strong>Zhi Shi.</strong></p></details><details><summary><?php echo s($qitext('Chief Qi regulator and gynecologic first choice?','¿Jefa de reguladoras de Qi y primera opción ginecológica?'));?></summary><p><strong>Xiang Fu.</strong></p></details><details><summary><?php echo s($qitext('Cold-Phlegm cough versus Middle-Jiao Dampness?','¿Tos por Flema-Frío frente a Humedad de Jiao Medio?'));?></summary><p><strong>Ju Hong</strong> <?php echo s($qitext('for the Lung cough;','para tos de Pulmón;'));?> <strong>Chen Pi</strong> <?php echo s($qitext('for the Middle.','para Jiao Medio.'));?></p></details><details><summary><?php echo s($qitext('Edema plus abdominal Qi stagnation?','¿Edema más estancamiento de Qi abdominal?'));?></summary><p><strong>Da Fu Pi.</strong></p></details><details><summary><?php echo s($qitext('Kidneys fail to grasp Qi with rebellious wheezing?','¿Riñones no captan Qi con sibilancia rebelde?'));?></summary><p><strong>Chen Xiang.</strong></p></details><details><summary><?php echo s($qitext('Liver-Qi stagnation with Heat and toxicity warning?','¿Estancamiento de Qi de Hígado con Calor y advertencia de toxicidad?'));?></summary><p><strong>Chuan Lian Zi.</strong></p></details></div></section>

